def write_generated_ownership(root: Path, generated: list[Path]) -> dict[str, Any]:
    files = sorted(path.relative_to(root).as_posix() for path in generated if path.is_file())
    record = {"schema_version": 1, "status": "ready", "files": files}
    json_write(root / ".ckb-generated-files.json", record)
    return record

def _payload_from_package(package: Path, temporary: Path) -> Path:
    package = package.expanduser().resolve()
    if package.is_dir():
        return package
    if not package.is_file() or package.suffix.casefold() != ".zip":
        raise CkbError(f"Obsidian plugin package must be a directory or ZIP: {package}")
    with zipfile.ZipFile(package) as archive:
        if archive.testzip():
            raise CkbError(f"Obsidian plugin ZIP CRC failed: {package}")
        names = set(archive.namelist())
        prefix = ""
        if "manifest.json" not in names:
            candidates = sorted(name for name in names if name.endswith("/manifest.json"))
            if len(candidates) != 1:
                raise CkbError("Obsidian plugin ZIP must contain one manifest.json")
            prefix = candidates[0][:-len("manifest.json")]
        for name in REQUIRED_FILES:
            member = prefix + name
            if member not in names:
                raise CkbError(f"Obsidian plugin ZIP is missing {name}")
            target = temporary / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(archive.read(member))
        for name in OPTIONAL_FILES:
            member = prefix + name
            if member in names:
                (temporary / name).write_bytes(archive.read(member))
    return temporary

def _validate_payload(root: Path) -> dict[str, Any]:
    missing = [name for name in REQUIRED_FILES if not (root / name).is_file()]
    if missing:
        raise CkbError(f"Obsidian plugin payload is incomplete: {missing}")
    manifest = json_load(root / "manifest.json")
    if manifest.get("id") != PLUGIN_ID:
        raise CkbError(f"unexpected Obsidian plugin id: {manifest.get('id')}")
    version = str(manifest.get("version") or "").strip()
    if not version:
        raise CkbError("Obsidian plugin manifest has no version")
    return manifest

def _registered_payload(registry: Path | None = None) -> tuple[dict[str, Any], Path]:
    registry = (registry or default_obsidian_plugin_registry()).expanduser().resolve()
    if not registry.is_file():
        raise CkbError("no active Obsidian plugin package is registered; run obsidian-plugin register")
    record = json_load(registry)
    payload = Path(str(record.get("payload") or "")).resolve()
    manifest = _validate_payload(payload)
    if str(manifest["version"]) != str(record.get("version")):
        raise CkbError("registered Obsidian plugin payload version drifted")
    return record, payload

def remove_obsidian_plugin(output: Path) -> dict[str, Any]:
    output = output.resolve()
    vault = output / "human"
    destination = vault / ".obsidian" / "plugins" / PLUGIN_ID
    if destination.exists():
        safe_rmtree(destination, vault / ".obsidian" / "plugins")
    community_path = vault / ".obsidian" / "community-plugins.json"
    if community_path.is_file():
        community = json_load(community_path)
        if isinstance(community, list):
            json_write(community_path, [value for value in community if value != PLUGIN_ID])
    (output / "workspace-meta" / "obsidian-plugin.json").unlink(missing_ok=True)
    from .output_contract import remove_output_contract

    remove_output_contract(vault)
    return {"schema_version": 1, "status": "removed", "plugin_id": PLUGIN_ID, "output": str(output)}

def deploy_registered_plugin_if_available(vault: Path, output: Path | None = None) -> dict[str, Any]:
    registry = default_obsidian_plugin_registry()
    if not registry.is_file():
        return {"status": "not-registered"}
    result = deploy_obsidian_plugin_to_vault(vault, registry)
    if output is not None:
        from .output_contract import project_output_contract

        result["output_contract"] = project_output_contract(output, vault)
    return result

def _journal_lock(root: Path) -> Iterator[None]:
    root.mkdir(parents=True, exist_ok=True)
    lock = root / ".lock"
    deadline = time.monotonic() + 5.0
    descriptor: int | None = None
    while descriptor is None:
        try:
            descriptor = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            os.write(descriptor, str(os.getpid()).encode("ascii"))
        except FileExistsError:
            try:
                if time.time() - lock.stat().st_mtime > 30:
                    lock.unlink(missing_ok=True)
                    continue
            except FileNotFoundError:
                continue
            if time.monotonic() >= deadline:
                raise CkbError(f"operation journal is busy: {lock}")
            time.sleep(0.05)
    try:
        yield
    finally:
        if descriptor is not None:
            os.close(descriptor)
        lock.unlink(missing_ok=True)

def _read_shard(path: Path) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    if not path.is_file():
        return records
    for line_number, line in enumerate(path.read_text(encoding="utf-8-sig").splitlines(), start=1):
        if not line.strip():
            continue
        try:
            value = json.loads(line)
        except json.JSONDecodeError as exc:
            raise CkbError(f"invalid operation journal JSONL at {path}:{line_number}: {exc}") from exc
        if not isinstance(value, dict):
            raise CkbError(f"operation journal record must be an object: {path}:{line_number}")
        records.append(value)
    return records

def _state(root: Path) -> dict[str, Any]:
    path = root / "state.json"
    if not path.is_file():
        return {
            "schema_version": OPERATION_JOURNAL_SCHEMA_VERSION,
            "dropped_records": 0,
            "expired_records": 0,
            "deduplicated_records": 0,
        }
    value = json_load(path)
    if not isinstance(value, dict):
        raise CkbError(f"operation journal state must be an object: {path}")
    return value

def _prune_expired(root: Path, today: date, state: dict[str, Any]) -> None:
    cutoff = _retention_cutoff(today)
    for path in sorted(root.glob("*.jsonl")):
        matched = _SHARD_NAME.fullmatch(path.name)
        if not matched:
            continue
        shard_date = date.fromisoformat(matched.group(1))
        if shard_date >= cutoff:
            continue
        state["expired_records"] = int(state.get("expired_records", 0)) + len(_read_shard(path))
        path.unlink()

def _all_events(root: Path) -> list[dict[str, Any]]:
    events: list[dict[str, Any]] = []
    for path in sorted(root.glob("*.jsonl")):
        if _SHARD_NAME.fullmatch(path.name):
            events.extend(_read_shard(path))
    return events

def _relative_evidence(output: Path, result: dict[str, Any]) -> list[str]:
    evidence: set[str] = set()
    for key in sorted(_EVIDENCE_KEYS):
        value = result.get(key)
        values = value if isinstance(value, list) else [value]
        for candidate in values:
            if not isinstance(candidate, str) or not candidate.strip():
                continue
            path = Path(candidate)
            if not path.is_absolute():
                path = output / path
            try:
                resolved = path.resolve()
            except OSError:
                continue
            if not resolved.exists() or not path_inside(resolved, output):
                continue
            evidence.add(resolved.relative_to(output).as_posix())
    return sorted(evidence)[:8]

def _operation_type(command: str) -> str | None:
    root = command.split(":", 1)[0]
    if root in {"init", "run", "build-chunk", "review-chunk", "review-pack", "merge", "finalize", "human-refresh", "reindex", "migrate", "relink"}:
        return "compile"
    if root in {"query", "retrieve", "brief", "keyword-benchmark", "context", "coverage", "entity", "neighbors", "source", "changes", "path", "explain", "status"}:
        return "query"
    if root == "maintain":
        return "maintenance"
    if command == "gaps:list":
        return "query"
    if command == "gaps:audit":
        return "audit"
    if command in {"gaps:create", "gaps:resolve"}:
        return "record"
    if root == "audit" or command in {"reference:audit", "feedback:audit", "agent-policy:check", "migrate:audit"}:
        return "audit"
    if root == "record" or command in {
        "reference:ingest",
        "reference:review",
        "reference:rollback",
        "feedback:create",
        "feedback:resolve",
        "workspace:session-start",
        "workspace:session-finish",
        "automation:review",
    }:
        return "record"
    return None

def record_cli_operation(args: Any, result: Any) -> dict[str, Any] | None:
    if str(getattr(args, "command", "")) == "operations" or not isinstance(result, dict):
        return None
    if result.get("operation_journal_recorded") is True:
        return None
    output_value = getattr(args, "out", None)
    if output_value is None:
        return None
    output = Path(output_value).resolve()
    if not (output / "state.json").is_file():
        return None
    command = _command_name(args)
    operation = _operation_type(command)
    if operation is None:
        return None
    status = str(result.get("status") or "completed")
    evidence = _relative_evidence(output, result)
    return record_operation(output, operation, command, status, evidence)

def list_operations(output: Path, operation: str | None = None, result_status: str | None = None, limit: int = 50) -> dict[str, Any]:
    if operation is not None and operation not in OPERATION_TYPES:
        raise CkbError(f"unsupported operation filter: {operation}")
    if limit < 1 or limit > 500:
        raise CkbError("operation list limit must be between 1 and 500")
    events = _all_events(_root(output))
    selected = [
        item
        for item in events
        if (operation is None or item.get("operation") == operation)
        and (result_status is None or item.get("result_status") == result_status)
    ]
    return {
        "schema_version": OPERATION_JOURNAL_SCHEMA_VERSION,
        "status": "ready",
        "filters": {"operation": operation, "result_status": result_status},
        "count": len(selected),
        "operations": selected[-limit:][::-1],
    }

def _event_errors(item: dict[str, Any], path: Path, line_number: int) -> list[str]:
    prefix = f"{path.name}:{line_number}"
    errors = []
    if set(item) != _EVENT_FIELDS:
        errors.append(f"{prefix}: fields differ from the fixed operation schema")
        return errors
    if item.get("schema_version") != OPERATION_JOURNAL_SCHEMA_VERSION:
        errors.append(f"{prefix}: schema version mismatch")
    if item.get("operation") not in OPERATION_TYPES:
        errors.append(f"{prefix}: unsupported operation type")
    if not isinstance(item.get("command"), str) or not _SAFE_TOKEN.fullmatch(item["command"]):
        errors.append(f"{prefix}: invalid command token")
    if not isinstance(item.get("result_status"), str) or not _SAFE_TOKEN.fullmatch(item["result_status"]):
        errors.append(f"{prefix}: invalid result status token")
    if not isinstance(item.get("event_id"), str) or not item["event_id"].startswith("operation-"):
        errors.append(f"{prefix}: invalid event id")
    if not isinstance(item.get("recorded_at_utc"), str) or len(item["recorded_at_utc"]) != 20:
        errors.append(f"{prefix}: invalid recorded timestamp")
    evidence = item.get("evidence_paths")
    if not isinstance(evidence, list) or len(evidence) > 8:
        errors.append(f"{prefix}: evidence_paths must be a bounded list")
    else:
        for value in evidence:
            if not isinstance(value, str):
                errors.append(f"{prefix}: evidence path must be text")
                continue
            relative = PurePosixPath(value)
            if relative.is_absolute() or ".." in relative.parts:
                errors.append(f"{prefix}: evidence path escapes OUTPUT")
    return errors

def _runtime_binding(output: Path) -> tuple[Path, Path]:
    record_path = output / "workspace-meta/agent-protocol.json"
    record = json_load(record_path) if record_path.is_file() else {}
    python = Path(str(record.get("python") or sys.executable)).resolve()
    ckb = Path(str(record.get("ckb") or _default_ckb())).resolve()
    return python, ckb

def expected_output_contract(output: Path, vault: Path) -> dict[str, Any]:
    output = output.resolve()
    vault = vault.resolve()
    python, ckb = _runtime_binding(output)
    return output_contract_for_runtime(output, vault, python, ckb)

def _update_ownership(vault: Path, *, present: bool) -> None:
    ownership_path = vault / ".ckb-generated-files.json"
    if not ownership_path.is_file():
        return
    ownership = json_load(ownership_path)
    files = {str(value) for value in ownership.get("files", [])}
    relative = OUTPUT_CONTRACT_RELATIVE.as_posix()
    if present:
        files.add(relative)
    else:
        files.discard(relative)
    ownership["files"] = sorted(files)
    json_write(ownership_path, ownership)

def remove_output_contract(vault: Path) -> dict[str, Any]:
    vault = vault.resolve()
    path = vault / OUTPUT_CONTRACT_RELATIVE
    path.unlink(missing_ok=True)
    parent = path.parent
    if parent.is_dir() and not any(parent.iterdir()):
        parent.rmdir()
    _update_ownership(vault, present=False)
    return {"schema_version": OUTPUT_CONTRACT_SCHEMA_VERSION, "status": "removed", "path": str(path)}

def _merge_known(default: Any, supplied: Any, path: str) -> Any:
    if isinstance(default, dict):
        if not isinstance(supplied, dict):
            raise CkbError(f"page config {path or '<root>'} must be an object")
        unknown = sorted(set(supplied) - set(default))
        if unknown:
            raise CkbError(f"page config has unknown keys at {path or '<root>'}: {unknown}")
        return {
            key: _merge_known(value, supplied[key], f"{path}.{key}".strip(".")) if key in supplied else copy.deepcopy(value)
            for key, value in default.items()
        }
    return copy.deepcopy(supplied)

def _integer(value: Any, path: str, minimum: int, maximum: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or not minimum <= value <= maximum:
        raise CkbError(f"page config {path} must be an integer in [{minimum}, {maximum}]")
    return value

def _section_list(config: dict[str, Any], name: str) -> None:
    value = config["content"][name]
    if not isinstance(value, list) or any(not isinstance(item, str) for item in value):
        raise CkbError(f"page config content.{name} must be a string array")
    if len(value) != len(set(value)):
        raise CkbError(f"page config content.{name} contains duplicate sections")
    unknown = sorted(set(value) - _SECTION_SETS[name])
    if unknown:
        raise CkbError(f"page config content.{name} has unknown sections: {unknown}")
    missing = sorted(_REQUIRED_SECTIONS[name] - set(value))
    if missing:
        raise CkbError(
            f"page config content.{name} omits audited required sections: {missing}"
        )

def normalize_page_config(value: dict[str, Any]) -> dict[str, Any]:
    """Merge a partial user JSON with defaults and enforce the audit contract."""
    if not isinstance(value, dict):
        raise CkbError("page config root must be a JSON object")
    if value.get("schema_version") != PAGE_CONFIG_SCHEMA_VERSION:
        raise CkbError(
            f"page config schema_version must be {PAGE_CONFIG_SCHEMA_VERSION}"
        )
    config = _merge_known(DEFAULT_PAGE_CONFIG, value, "")

    limits = config["page_limits"]
    for key in ("ordinary_file", "core_file", "adjacent_file"):
        limits[key] = _integer(limits[key], f"page_limits.{key}", 0, 32)
    for key in ("core_per_entry", "adjacent_per_entry"):
        limits[key] = _integer(limits[key], f"page_limits.{key}", 0, 64)

    for name in _SECTION_SETS:
        _section_list(config, name)
    fields = config["content"]["overview_fields"]
    if (
        not isinstance(fields, list)
        or not fields
        or len(fields) != len(set(fields))
        or any(value not in {"meaning", "role"} for value in fields)
    ):
        raise CkbError(
            "page config content.overview_fields must contain one or both of: meaning, role"
        )
    if config["content"]["appendix_mode"] not in {"collapsed", "expanded"}:
        raise CkbError("page config content.appendix_mode must be collapsed or expanded")
    headings = config["content"]["headings"]
    for key, heading in headings.items():
        if not isinstance(heading, str) or not heading.strip() or len(heading) > 64 or "\n" in heading or "\r" in heading:
            raise CkbError(f"page config content.headings.{key} must be one non-empty line of at most 64 characters")
        headings[key] = heading.strip()

    relation_limits = config["relation_limits"]
    for key in ("direct", "aggregate", "test", "boundary"):
        relation_limits[key] = _integer(relation_limits[key], f"relation_limits.{key}", 0, 200)

    context = config["context"]
    context["module_max_tokens"] = _integer(context["module_max_tokens"], "context.module_max_tokens", 1_000, 1_000_000)
    context["task_max_tokens"] = _integer(context["task_max_tokens"], "context.task_max_tokens", 500, 1_000_000)
    context["total_max_tokens"] = _integer(context["total_max_tokens"], "context.total_max_tokens", 1_000, 2_000_000)
    context["reserved_agent_tokens"] = _integer(context["reserved_agent_tokens"], "context.reserved_agent_tokens", 0, 1_000_000)
    context["bytes_per_token"] = _integer(context["bytes_per_token"], "context.bytes_per_token", 1, 16)
    if context["task_max_tokens"] > context["module_max_tokens"]:
        raise CkbError("page config context.task_max_tokens must not exceed module_max_tokens")
    if context["module_max_tokens"] + context["reserved_agent_tokens"] > context["total_max_tokens"]:
        raise CkbError(
            "page config context.module_max_tokens plus reserved_agent_tokens must not exceed total_max_tokens"
        )

    review = config["review_packs"]
    for kind in ("page", "appendix"):
        review[kind]["max_files"] = _integer(review[kind]["max_files"], f"review_packs.{kind}.max_files", 1, 200)
        review[kind]["max_items"] = _integer(review[kind]["max_items"], f"review_packs.{kind}.max_items", 1, 5_000)
        review[kind]["max_tokens"] = _integer(review[kind]["max_tokens"], f"review_packs.{kind}.max_tokens", 500, 1_000_000)
        if review[kind]["max_tokens"] > context["total_max_tokens"] - context["reserved_agent_tokens"]:
            raise CkbError(
                f"page config review_packs.{kind}.max_tokens exceeds the non-Agent context budget"
            )
    return config

def page_config_bytes(config: dict[str, Any]) -> bytes:
    normalized = normalize_page_config(config)
    return (json.dumps(normalized, ensure_ascii=False, indent=2) + "\n").encode("utf-8")

def write_page_config(path: Path, config: dict[str, Any], *, overwrite: bool = False) -> dict[str, Any]:
    resolved = path.resolve()
    if resolved.exists() and not overwrite:
        raise CkbError(f"page config output already exists: {resolved}; use --force to replace it")
    resolved.parent.mkdir(parents=True, exist_ok=True)
    content = page_config_bytes(config)
    resolved.write_bytes(content)
    return {
        "schema_version": PAGE_CONFIG_SCHEMA_VERSION,
        "path": str(resolved),
        "sha256": hashlib.sha256(content).hexdigest(),
        "status": "passed",
    }

def _language(language: str):
    try:
        from tree_sitter import Language
        modules = {
            "python": "tree_sitter_python",
            "javascript": "tree_sitter_javascript",
            "c": "tree_sitter_c",
            "cpp": "tree_sitter_cpp",
            "csharp": "tree_sitter_c_sharp",
        }
        module = __import__(modules[language])
        return Language(module.language())
    except Exception as exc:
        raise DependencyError(f"Tree-sitter runtime for {language} is unavailable: {exc}") from exc

def _walk(node) -> Iterator[Any]:
    stack = [node]
    while stack:
        current = stack.pop()
        yield current
        stack.extend(reversed(current.children))

def _byte_position(source: bytes, byte_offset: int) -> tuple[int, int]:
    """Compute 1-based line and UTF-8 byte column without Node Point access."""
    previous_newline = source.rfind(b"\n", 0, byte_offset)
    return source.count(b"\n", 0, byte_offset) + 1, byte_offset - (previous_newline + 1)

def _find_name(node, source: bytes, retained_nodes: list[Any]) -> tuple[str, int, int] | None:
    for field in NAME_FIELDS:
        child = node.child_by_field_name(field)
        if child is not None:
            candidates = [child, *_walk(child)]
            retained_nodes.extend(candidates)
            for value in candidates:
                if value.type in {"identifier", "type_identifier", "field_identifier", "property_identifier", "namespace_identifier"}:
                    line, column = _byte_position(source, value.start_byte)
                    return _node_text(value, source), line, column
    fallback_nodes = list(_walk(node))
    retained_nodes.extend(fallback_nodes)
    for child in fallback_nodes:
        if child.type in {"identifier", "type_identifier", "field_identifier", "property_identifier", "namespace_identifier"}:
            line, column = _byte_position(source, child.start_byte)
            return _node_text(child, source), line, column
    return None

def _public_evidence(language: str, source_text: str, node_text: str, name: str) -> bool:
    if language == "python":
        return not name.startswith("_")
    if language == "javascript":
        return bool(re.search(r"\bexport\b", source_text[max(0, source_text.find(node_text) - 80) : source_text.find(node_text) + 20]))
    return bool(re.search(r"\b(public|protected|internal|extern)\b", node_text)) or language in {"c", "cpp"}

def _single_statement_shape(node, source: bytes, kind: str) -> str | None:
    """Return a small deterministic hard-exclusion reason for thin declarations."""
    if kind == "accessor":
        return "accessor"
    if kind not in {"function", "method", "local_function", "constructor", "operator", "conversion_operator", "property", "indexer", "event"}:
        return None
    body = node.child_by_field_name("body")
    if body is None:
        # Expression-bodied C# members and declarations without a block.
        text = _node_text(node, source)
        if "=>" in text:
            return "single-expression-body"
        return None
    named = [child for child in body.named_children if child.type not in {"comment"}]
    if len(named) != 1:
        return None
    statement = named[0]
    text = _node_text(statement, source)
    if statement.type in {"return_statement", "expression_statement"}:
        if not re.search(r"\b(if|for|foreach|while|switch|try|catch|await|yield|throw|lock)\b", text):
            return "single-return-or-call"
    if statement.type in {"assignment_expression", "local_declaration_statement"}:
        return "single-assignment"
    return None

def _has_ancestor(node: Any, node_type: str) -> bool:
    current = node.parent
    while current is not None:
        if current.type == node_type:
            return True
        current = current.parent
    return False

def _cpp_explicit_class_instantiation_recovery(node: Any, source: bytes) -> dict[str, Any] | None:
    """Recognize the pinned grammar's sole missing-node shape for ``template class``."""
    if not node.is_missing or node.type != "identifier":
        return None
    parent = node.parent
    if parent is None or parent.type != "template_instantiation":
        return None
    type_node = parent.child_by_field_name("type")
    if type_node is None or type_node.type not in {"class_specifier", "struct_specifier"}:
        return None
    name_node = type_node.child_by_field_name("name")
    if name_node is None or name_node.type != "template_type":
        return None
    text = _node_text(parent, source).strip()
    if not re.match(r"^template\s+(?:class|struct)\b", text) or not text.endswith(";"):
        return None
    start_line, _ = _byte_position(source, parent.start_byte)
    end_line, _ = _byte_position(source, parent.end_byte)
    return {
        "kind": "tree-sitter-cpp-explicit-class-template-instantiation",
        "node_type": node.type,
        "start_line": start_line,
        "end_line": end_line,
    }

def _union_size(ranges: list[tuple[int, int]]) -> int:
    ordered = sorted((start, max(start, end)) for start, end in ranges)
    if not ordered:
        return 0
    total = 0
    current_start, current_end = ordered[0]
    for start, end in ordered[1:]:
        if start <= current_end:
            current_end = max(current_end, end)
            continue
        total += current_end - current_start
        current_start, current_end = start, end
    return total + current_end - current_start
